Here is a C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string filename, word;
    int count = 0;

    cout << "Enter the filename: ";
    cin >> filename;

    cout << "Enter the word to search for: ";
    cin >> word;

    ifstream file(filename);
    if (!file) {
        cerr << "Error opening file." << endl;
        return 1;
    }

    string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            count++;
            pos += word.length();
        }
    }

    cout << "The word '" << word << "' appears in the file " << count << " times." << endl;

    file.close();

    return 0;
}
```

