class QueueUsingStacks:
    def __init__(self):
        self.stack1 = []
        self.stack2 = []

    def enqueue(self, item):
        self.stack1.append(item)

    def dequeue(self):
        if not self.stack2:
            if not self.stack1:
                return None
            while self.stack1:
                self.stack2.append(self.stack1.pop())
        return self.stack2.pop()

    def is_empty(self):
        return not self.stack1 and not self.stack2

# Example Usage
queue = QueueUsingStacks()
queue.enqueue(1)
queue.enqueue(2)
queue.enqueue(3)

print(queue.dequeue())  # Output: 1
print(queue.dequeue())  # Output: 2
print(queue.dequeue())  # Output: 3
print(queue.dequeue())  # Output: None
``` 

In this implementation, we use `stack1` for enqueueing items and `stack2` for dequeueing items. When we want to dequeue an item, we first check if `stack2` is empty. If it is, we pop all items from `stack1` and push them onto `stack2` in reverse order. Then we pop an item from `stack2` to return as the dequeued item.
